+                deletedAt: null,
+              },
+            }),
+          },
+        }),
+      );
+    });
+
+    test('should return the remaining comments with the author mapped', async () => {
+      // Given
+      const createdAt = new Date('2026-10-01T10:00:00Z');
+      const updatedAt = new Date('2026-10-01T10:00:00Z');
+
+      // When
+      // @ts-ignore
+      prismaMock.article.findUnique.mockResolvedValue({
+        comments: [
+          {
+            id: 1,
+            createdAt,
+            updatedAt,
+            body: 'still here',
+            author: { username: 'RealWorld', bio: null, image: null, followedBy: [] },
