+        createdAt,
+        updatedAt: editedAt,
+        body: newBody,
+        author: {
+          username: 'RealWorld',
+          bio: null,
+          image: null,
+          following: false,
+        },
+      });
+
+      expect(prismaMock.comment.update).toHaveBeenCalledWith(
